const $=id=>document.getElementById(id); const inputEl=()=>$('input'), outEl=()=>$('output');
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const nums=s=>s.split(/[,;\s]+/).map(Number); const hex=()=>'#'+Math.floor(Math.random()*0x1000000).toString(16).padStart(6,'0');
function download(name,data,type='text/plain'){const a=document.createElement('a');a.href=typeof data==='string'?URL.createObjectURL(new Blob([data],{type})):URL.createObjectURL(data);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),800)}
async function digest(algo,s){const b=await crypto.subtle.digest(algo,new TextEncoder().encode(s));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function loadScript(src){return new Promise((res,rej)=>{if(document.querySelector(`script[src="${src}"]`))return res();const s=document.createElement('script');s.src=src;s.onload=res;s.onerror=rej;document.head.appendChild(s)})}
