async function imageRun(type,file){const bmp=await createImageBitmap(file);let w=bmp.width,h=bmp.height,tw=w,th=h;if(type==='imageResize'){tw=Number($('w').value)||w;th=Number($('h').value)||h} const c=document.createElement('canvas');c.width=tw;c.height=th;const x=c.getContext('2d'); if(type==='imageFilter')x.filter=$('filter').value; x.drawImage(bmp,0,0,tw,th); if(type==='imageCrop'){const cx=Number($('x').value)||0,cy=Number($('y').value)||0,cw=Number($('cw').value)||w,ch=Number($('ch').value)||h;const cc=document.createElement('canvas');cc.width=cw;cc.height=ch;cc.getContext('2d').drawImage(bmp,cx,cy,cw,ch,0,0,cw,ch);return [cc,'image/png']} if(type==='imageWatermark'){x.font=`${Math.max(18,Math.round(w/20))}px sans-serif`;x.fillStyle='rgba(255,255,255,.55)';x.fillText($('wm').value||'AppQuickUtils',20,h-30)} let mime='image/png',name='imagen.png'; if(['imageCompress','imageWebp'].includes(type)){mime='image/webp';name='imagen.webp'} if(type==='imageJpg'){mime='image/jpeg';name='imagen.jpg';x.fillStyle='#fff';x.globalCompositeOperation='destination-over';x.fillRect(0,0,tw,th)} const q=(Number($('quality')?.value)||85)/100; return [c,mime,name,q]}
async function fileRun(type){try{const files=[...($('file')?.files||[])];if(type==='textPdf'){await loadScript('https://cdn.jsdelivr.net/npm/jspdf@2.5.1/dist/jspdf.umd.min.js');const {jsPDF}=window.jspdf;const pdf=new jsPDF();const lines=pdf.splitTextToSize($('textInput').value||'',180);pdf.text(lines,15,20);pdf.save('appquickutils-documento.pdf');return}if(type==='qrPlus'){await loadScript('../../assets/qrcode-local.js');const text=$('textInput').value.trim()||'https://appquickutils.com';const QR=window.AppQuickUtilsQRCode; if(!QR||!QR.QRCode)throw Error('No se ha podido cargar el generador QR local.'); const q=new QR.QRCode(0,QR.ErrorCorrectLevel.M);q.addData(text);q.make();const count=q.getModuleCount(),scale=Math.max(4,Math.floor(400/count)),margin=4,size=(count+margin*2)*scale;const c=document.createElement('canvas');c.width=size;c.height=size;const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,size,size);ctx.fillStyle='#000';for(let r=0;r<count;r++){for(let col=0;col<count;col++){if(q.isDark(r,col))ctx.fillRect((col+margin)*scale,(r+margin)*scale,scale,scale)}}const a=document.createElement('a');a.href=c.toDataURL('image/png');a.download='qr-appquickutils.png';a.click();$('preview').innerHTML='';$('preview').appendChild(c);return}if(type.startsWith('image')&&!files.length&&type!=='imageBase64')throw Error('Selecciona una imagen');
 if(['imageCompress','imageResize','imageWebp','imagePng','imageJpg','imageCrop','imageFilter','imageWatermark'].includes(type)){const [c,mime,name,q]=await imageRun(type,files[0]);c.toBlob(b=>download(name||'imagen.png',b,mime),mime,q);$('preview').innerHTML=`<img src="${c.toDataURL(mime,q)}" class="max-h-80 rounded-xl border border-slate-700">`;return}
 if(type==='imageBase64'){const f=files[0];if(!f)throw Error('Selecciona una imagen');const r=new FileReader();r.onload=()=>{outEl()?.textContent&&(outEl().textContent=r.result)}; if(!$('output')){const p=document.createElement('pre');p.id='output';p.className='whitespace-pre-wrap break-all mt-4 bg-slate-950 p-4 rounded-xl';$('preview').after(p)} r.onload=()=>document.getElementById('output').textContent=r.result;r.readAsDataURL(f);return}
 if(type==='imagesPdf'){await loadScript('https://cdn.jsdelivr.net/npm/jspdf@2.5.1/dist/jspdf.umd.min.js');const {jsPDF}=window.jspdf;const pdf=new jsPDF();for(let i=0;i<files.length;i++){if(i)pdf.addPage();const b=await createImageBitmap(files[i]);const ratio=Math.min(180/b.width,260/b.height);const data=await blobData(files[i]);const fmt=(files[i].type||'image/jpeg').includes('png')?'PNG':(files[i].type||'').includes('webp')?'WEBP':'JPEG';pdf.addImage(data,fmt,15,15,b.width*ratio,b.height*ratio)}pdf.save('imagenes.pdf');return}
 if(type.startsWith('pdf')){await loadScript('https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js');const {PDFDocument}=PDFLib;if(type==='pdfMerge'){if(files.length<2)throw Error('Selecciona al menos 2 PDF');const out=await PDFDocument.create();for(const f of files){const d=await PDFDocument.load(await f.arrayBuffer());const pages=await out.copyPages(d,d.getPageIndices());pages.forEach(p=>out.addPage(p))}download('pdf-unido.pdf',await out.save(),'application/pdf');return}const f=files[0];if(!f)throw Error('Selecciona un PDF');const d=await PDFDocument.load(await f.arrayBuffer());if(type==='pdfText'){await loadScript('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js');const pdfjs=window.pdfjsLib;if(!pdfjs)throw Error('No se pudo cargar el motor PDF.');pdfjs.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';const pdf=await pdfjs.getDocument({data:await f.arrayBuffer()}).promise;let text='';for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i);const c=await page.getTextContent();text+=`--- Página ${i} ---\n`+c.items.map(x=>x.str).join(' ')+'\n\n'}document.getElementById('preview').textContent=text.trim()||'No se encontró texto seleccionable en el PDF.';return}if(type==='pdfInfo'){document.getElementById('preview').textContent=`Páginas / Pages: ${d.getPageCount()}\nTamaño / Size: ${(f.size/1024/1024).toFixed(2)} MB`;return}if(type==='pdfSplit'){const p=d.getPageIndices();for(let i=0;i<p.length;i++){const o=await PDFDocument.create();const [pg]=await o.copyPages(d,[p[i]]);o.addPage(pg);download(`pagina-${i+1}.pdf`,await o.save(),'application/pdf')}return}if(type==='pdfCompress'){download('pdf-optimizado.pdf',await d.save({useObjectStreams:true}),'application/pdf');return}if(type==='pdfPage'){const n=Math.max(1,Math.min(d.getPageCount(),Number($('textInput').value)||1))-1;const o=await PDFDocument.create();const [pg]=await o.copyPages(d,[n]);o.addPage(pg);download(`pagina-${n+1}.pdf`,await o.save(),'application/pdf');return}if(type==='pdfImage'){await loadScript('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js');const pdfjs=window.pdfjsLib;if(!pdfjs)throw Error('No se pudo cargar el motor PDF.');pdfjs.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';const pdf=await pdfjs.getDocument({data:await f.arrayBuffer()}).promise;const preview=document.getElementById('preview');preview.innerHTML='';for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i);const viewport=page.getViewport({scale:1.5});const c=document.createElement('canvas');c.width=viewport.width;c.height=viewport.height;await page.render({canvasContext:c.getContext('2d'),viewport}).promise;const a=document.createElement('a');a.href=c.toDataURL('image/png');a.download=`pagina-${i}.png`;a.className='inline-flex items-center gap-2 mr-2 mb-2 px-4 py-2 rounded-xl bg-emerald-500 text-slate-950 font-bold';a.textContent=`Descargar página ${i}`;preview.append(c,a,document.createElement('br'));}return}}
 }catch(e){document.getElementById('preview').textContent='Error: '+e.message}}
function blobData(file){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)})}
