  ['dragenter','dragover'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.add('border-emerald-400','bg-emerald-400/5')}));['dragleave','drop'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.remove('border-emerald-400','bg-emerald-400/5')}));drop.addEventListener('drop',e=>{if(e.dataTransfer.files[0]){try{file.files=e.dataTransfer.files}catch{}file.dispatchEvent(new Event('change',{bubbles:true}))}});
  $('copyAudio').onclick=async()=>{if(output.value)await navigator.clipboard.writeText(output.value)};$('downloadAudio').onclick=()=>{if(output.value)download('transcripcion-appquickutils.txt',output.value)};$('clearAudio').onclick=()=>{file.value='';name.textContent='Ningún archivo seleccionado';output.value='';status.textContent='Listo para transcribir.';progress.textContent='0%'};
  $('transcribeAudio').onclick=async()=>{try{const f=file.files[0];if(!f)throw Error('Selecciona un archivo de audio.');status.textContent='Cargando el motor de transcripción…';progress.textContent='10%';const {pipeline}=await import('https://cdn.jsdelivr.net/npm/@huggingface/transformers@4.3.0/+esm');const device=$('audioDevice').value==='webgpu'?'webgpu':'wasm';const transcriber=await pipeline('automatic-speech-recognition','onnx-community/whisper-tiny',{device,dtype:'q8'});progress.textContent='35%';status.textContent='Preparando el audio…';const ctx=new (window.AudioContext||window.webkitAudioContext)();const buf=await ctx.decodeAudioData(await f.arrayBuffer());const target=16000,length=Math.ceil(buf.duration*target),mono=new Float32Array(length);for(let ch=0;ch<buf.numberOfChannels;ch++){const data=buf.getChannelData(ch),ratio=length/data.length;for(let i=0;i<length;i++)mono[i]+=(data[Math.min(data.length-1,Math.floor(i/ratio))]||0)/buf.numberOfChannels}const opts={chunk_length_s:30,stride_length_s:5};const lang=$('audioLang').value;if(lang)opts.language=lang;progress.textContent='55%';status.textContent='Transcribiendo en tu navegador…';const result=await transcriber(mono,opts);output.value=(result.text||'').trim();progress.textContent='100%';status.textContent='Transcripción terminada. Revisa nombres, números y términos técnicos.';await ctx.close()}catch(e){status.textContent='No se ha podido transcribir: '+e.message;progress.textContent='0%'}};return true;
