 mikm:{title:'Millas a kilómetros',desc:'Convierte millas a kilómetros.',fields:[['distance','Distancia','10','mi']],calc:v=>`Resultado: ${(Number(v.distance)*1.609344).toFixed(3)} km`},
 kgp:{title:'Kilogramos a libras',desc:'Convierte kilogramos a libras.',fields:[['weight','Peso','10','kg']],calc:v=>`Resultado: ${(Number(v.weight)*2.2046226218).toFixed(2)} lb`},
 pkg:{title:'Libras a kilogramos',desc:'Convierte libras a kilogramos.',fields:[['weight','Peso','10','lb']],calc:v=>`Resultado: ${(Number(v.weight)*0.45359237).toFixed(2)} kg`},
 mft:{title:'Metros a pies',desc:'Convierte metros a pies.',fields:[['length','Longitud','10','m']],calc:v=>`Resultado: ${(Number(v.length)*3.28084).toFixed(2)} ft`},
 ftm:{title:'Pies a metros',desc:'Convierte pies a metros.',fields:[['length','Longitud','10','ft']],calc:v=>`Resultado: ${(Number(v.length)*0.3048).toFixed(2)} m`},
 lgal:{title:'Litros a galones',desc:'Convierte litros a galones.',fields:[['volume','Volumen','10','L']],calc:v=>`Resultado: ${(Number(v.volume)*0.264172).toFixed(3)} gal`},
 bytes:{title:'Conversor de bytes',desc:'Convierte bytes a KB, MB, GB y TB.',fields:[['bytes','Bytes','2048','B']],calc:v=>{const n=Number(v.bytes);if(!(n>=0))return 'Introduce una cantidad válida.';return `KB: ${(n/1024).toFixed(2)}\nMB: ${(n/1048576).toFixed(4)}\nGB: ${(n/1073741824).toFixed(6)}`}},
