 if(!c||!root)return false;
 root.innerHTML=`<section class="aq-calc-shell"><div class="aq-calc-form"><div class="aq-calc-kicker"><span class="aq-calc-icon">∑</span><div><span>Calculadora</span><strong>${esc(c.title)}</strong></div></div><p class="aq-calc-desc">${esc(c.desc)}</p><div class="aq-calc-fields">${c.fields.map(([id,label,val,unit])=>`<label class="aq-field"><span>${esc(label)}${unit&&unit!=='YYYY-MM-DD'?` <em>${esc(unit)}</em>`:''}</span>${String(val).includes('\n')?`<textarea id="safe-${id}" class="aq-input aq-input-area">${esc(val)}</textarea>`:`<input id="safe-${id}" class="aq-input" inputmode="decimal" type="${unit==='YYYY-MM-DD'?'date':'text'}" value="${esc(val)}">`}</label>`).join('')}</div><div class="aq-calc-actions"><button id="safe-run" class="aq-primary">Calcular resultado</button><button id="safe-clear" class="aq-secondary">Limpiar</button></div></div><div class="aq-calc-result"><div class="aq-result-top"><span>Resultado</span></div><div id="safe-output" class="aq-result-value" aria-live="polite">Introduce tus valores y calcula.</div></div></section>`;
 const read=()=>Object.fromEntries(c.fields.map(([id])=>[id,$('safe-'+id).value.trim()]));
